content:
:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --accent-cyan: #06b6d4;
  --accent-cyan-hover: #0891b2;
  --accent-blue: #3b82f6;
  --accent-purple: #8b5cf6;
  --accent-danger: #ef4444;
  --accent-danger-hover: #dc2626;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border-color: #334155;
  --border-focus: #38bdf8;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.2);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.3), 0 4px 6px -4px rgba(0, 0, 0, 0.3);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

.sim-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 16px;
  max-width: 1200px;
  margin: 0 auto;
  gap: 16px;
}

.sim-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 8px 16px;
  gap: 4px;
}

.sim-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 50%, #c084fc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 10px rgba(56, 189, 248, 0.2);
}

.sim-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
  max-width: 600px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  max-height: 70vh;
  background-color: #020617;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.6), var(--shadow-lg);
  overflow: hidden;
  touch-action: none;
  display: flex;
  justify-content: center;
  align-items: center;
}

.canvas-element {
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

.canvas-hint {
  position: absolute;
  top: 12px;
  left: 12px;
  padding: 6px 12px;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
  pointer-events: none;
  user-select: none;
  z-index: 5;
}

.controls-panel {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 16px;
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  justify-content: center;
}

.control-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  user-select: none;
}

.control-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.9rem;
  color: var(--accent-cyan);
  background-color: var(--bg-tertiary);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  font-weight: 700;
}

.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  outline: none;
  transition: background 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.control-slider:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.3);
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(6, 182, 212, 0.6);
  border: 2px solid #ffffff;
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--accent-cyan-hover);
}

.control-slider::-webkit-slider-thumb:active {
  transform: scale(0.95);
}

.control-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(6, 182, 212, 0.6);
  border: 2px solid #ffffff;
  transition: transform 0.1s ease;
}

.control-slider::-moz-range-thumb:hover {
  transform: scale(1.15);
}

.checkbox-group {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  user-select: none;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
  padding: 6px 0;
}

.checkbox-group input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent-cyan);
  cursor: pointer;
  border-radius: 4px;
  outline: none;
  transition: box-shadow 0.15s ease-in-out;
}

.checkbox-group input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.3);
}

.button-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  outline: none;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  touch-action: manipulation;
  min-height: 42px;
  text-decoration: none;
  user-select: none;
  box-shadow: var(--shadow-sm);
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.35);
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent-cyan) 0%, var(--accent-blue) 100%);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(6, 182, 212, 0.3);
}

.btn-primary:hover {
  filter: brightness(1.1);
  box-shadow: 0 6px 16px rgba(6, 182, 212, 0.4);
}

.btn-secondary {
  background-color: var(--bg-tertiary);
  color: var(--text-main);
  border-color: var(--border-color);
}

.btn-secondary:hover {
  background-color: #475569;
  border-color: #64748b;
}

.btn-danger {
  background-color: rgba(239, 68, 68, 0.15);
  color: var(--accent-danger);
  border-color: rgba(239, 68, 68, 0.3);
}

.btn-danger:hover {
  background-color: var(--accent-danger);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.3);
}

.stats-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid var(--border-color);
  border-radius: 9999px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
}

.stats-badge strong {
  color: var(--accent-cyan);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.9rem;
}

@media (max-width: 640px) {
  .sim-container {
    padding: 10px;
    gap: 12px;
  }

  .sim-title {
    font-size: 1.35rem;
  }

  .sim-subtitle {
    font-size: 0.8rem;
  }

  .canvas-wrapper {
    aspect-ratio: 4 / 3;
    max-height: 60vh;
  }

  .controls-panel {
    grid-template-columns: 1fr;
    padding: 14px;
    gap: 14px;
  }

  .button-group {
    flex-direction: column;
    width: 100%;
  }

  .btn {
    width: 100%;
  }

  .canvas-hint {
    font-size: 0.7rem;
    padding: 4px 8px;
  }
}

/**
 * 物理シミュレーション空間内のボール情報
 */
export interface Ball {
  /** 一意なボール識別子 */
  id: number;
  /** X座標 (px) */
  x: number;
  /** Y座標 (px) */
  y: number;
  /** X軸方向の初速/移動速度 (px/frame) */
  vx: number;
  /** Y軸方向の初速/移動速度 (px/frame) */
  vy: number;
  /** ボールの半径 (px) */
  radius: number;
  /** 描画カラー (HEXまたはCSSカラー文字列) */
  color: string;
  /**
   * 壁・床またはボール同士の衝突累積回数
   * デバッグ・統計情報表示や視覚的エフェクトに利用可能
   */
  bounceCount?: number;
}

/**
 * 物理エンジンのリアルタイム設定パラメータ
 */
export interface SimSettings {
  /**
   * 重力加速度 (G)
   * 許容範囲: 0.0 〜 2.0 (標準値: 0.5)
   * 単位: px / frame^2 相当の加速度係数
   */
  gravity: number;

  /**
   * 反発係数 (弾力 / 復元係数)
   * 許容範囲: 0.1 〜 0.99 (標準値: 0.75)
   * 衝突後の速度残存率 (1.0で完全弾性衝突)
   */
  restitution: number;

  /**
   * 摩擦係数および空気抵抗による速度減衰率
   * 許容範囲: 0.950 〜 1.000 (標準値: 0.992)
   * 1フレームごとに速度に乗算される減衰係数 (1.0で減衰なし)
   */
  friction: number;

  /**
   * 残像エフェクト（移動軌跡の半透明重ね塗り）の有効化フラグ
   */
  trail: boolean;
}

/**
 * 物理シミュレーション操作パネルのProps
 */
export interface ControlsProps {
  /** 現在の物理パラメータ設定 */
  settings: SimSettings;
  /** パラメータ変更ハンドラ */
  onSettingsChange: (newSettings: SimSettings) => void;
  /** 現在キャンバス上に存在するボールの総数 */
  ballCount: number;
  /** 全ボール削除ハンドラ */
  onClear: () => void;
  /**
   * ボール一括追加ハンドラ
   * @param count 一度に追加するボールの個数（パフォーマンス保護のため通常 1〜50 個程度を推奨）
   */
  onAddMultiple: (count: number) => void;
  /** 設定を標準デフォルト値へ復元するハンドラ */
  onResetSettings: () => void;
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { Ball, SimSettings } from './types';
import Controls from './components/Controls';
import './index.css';

const DEFAULT_SETTINGS: SimSettings = {
  gravity: 0.5,
  restitution: 0.75,
  friction: 0.992,
  trail: true,
};

const BALL_COLORS = [
  '#06b6d4',
  '#3b82f6',
  '#8b5cf6',
  '#ec4899',
  '#f59e0b',
  '#10b981',
  '#38bdf8',
  '#a855f7',
  '#f43f5e',
  '#14b8a6',
];

export default function App() {
  const [settings, setSettings] = useState<SimSettings>(DEFAULT_SETTINGS);
  const [ballCount, setBallCount] = useState<number>(0);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>([]);
  const nextIdRef = useRef<number>(1);
  const settingsRef = useRef<SimSettings>(settings);
  const animationFrameRef = useRef<number>(0);
  const isInitializedRef = useRef<boolean>(false);

  // ドラッグ操作の状態管理
  const dragStartRef = useRef<{ x: number; y: number } | null>(null);
  const currentDragRef = useRef<{ x: number; y: number } | null>(null);

  // settings 変更を ref に即時同期
  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);

  // 初期ボールをキャンバスサイズ基準で生成
  const spawnInitialBalls = useCallback((width: number, height: number) => {
    const safeWidth = width > 0 ? width : 800;
    const safeHeight = height > 0 ? height : 450;
    const initialBalls: Ball[] = [];
    const count = 8;

    for (let i = 0; i < count; i++) {
      initialBalls.push({
        id: nextIdRef.current++,
        x: safeWidth * 0.1 + (i * (safeWidth * 0.8)) / Math.max(count - 1, 1),
        y: safeHeight * 0.15 + (i % 3) * (safeHeight * 0.08),
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.2) * 4,
        radius: 12 + Math.random() * 12,
        color: BALL_COLORS[i % BALL_COLORS.length],
        bounceCount: 0,
      });
    }

    ballsRef.current = initialBalls;
    setBallCount(initialBalls.length);
  }, []);

  // Canvasリサイズ対応と初回ボール初期化
  const handleResize = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const newWidth = Math.floor(rect.width);
    const newHeight = Math.floor(rect.height);

    if (canvas.width !== newWidth || canvas.height !== newHeight) {
      canvas.width = newWidth;
      canvas.height = newHeight;
    }

    if (!isInitializedRef.current && newWidth > 0 && newHeight > 0) {
      isInitializedRef.current = true;
      spawnInitialBalls(newWidth, newHeight);
    }
  }, [spawnInitialBalls]);

  useEffect(() => {
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [handleResize]);

  // 物理ループと描画
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let lastTime = performance.now();

    const loop = (currentTime: number) => {
      const dt = Math.min((currentTime - lastTime) / 16.666, 2.0);
      lastTime = currentTime;

      const currentSettings = settingsRef.current;
      const width = canvas.width;
      const height = canvas.height;

      // 画面のクリアまたは残像塗り
      if (currentSettings.trail) {
        ctx.fillStyle = 'rgba(2, 6, 23, 0.25)';
        ctx.fillRect(0, 0, width, height);
      } else {
        ctx.clearRect(0, 0, width, height);
      }

      const balls = ballsRef.current;
      const len = balls.length;

      // 1. 位置と速度の更新（重力・摩擦・壁床衝突）
      for (let i = 0; i < len; i++) {
        const b = balls[i];

        // 重力適用
        b.vy += currentSettings.gravity * dt;

        // 空気抵抗・床摩擦
        b.vx *= Math.pow(currentSettings.friction, dt);
        b.vy *= Math.pow(currentSettings.friction, dt);

        // 位置更新
        b.x += b.vx * dt;
        b.y += b.vy * dt;

        // 床衝突
        if (b.y + b.radius > height) {
          b.y = height - b.radius;
          b.vy = -b.vy * currentSettings.restitution;
          b.vx *= 0.98; // 床接地時の横滑り減速
          if (Math.abs(b.vy) < 0.2) b.vy = 0;
          b.bounceCount = (b.bounceCount || 0) + 1;
        }
        // 天井衝突
        else if (b.y - b.radius < 0) {
          b.y = b.radius;
          b.vy = -b.vy * currentSettings.restitution;
          b.bounceCount = (b.bounceCount || 0) + 1;
        }

        // 左右の壁衝突
        if (b.x + b.radius > width) {
          b.x = width - b.radius;
          b.vx = -b.vx * currentSettings.restitution;
          b.bounceCount = (b.bounceCount || 0) + 1;
        } else if (b.x - b.radius < 0) {
          b.x = b.radius;
          b.vx = -b.vx * currentSettings.restitution;
          b.bounceCount = (b.bounceCount || 0) + 1;
        }
      }

      // 2. ボール同士の衝突判定と反発（弾性衝突）
      for (let i = 0; i < len; i++) {
        for (let j = i + 1; j < len; j++) {
          const b1 = balls[i];
          const b2 = balls[j];

          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const distSq = dx * dx + dy * dy;
          const minDist = b1.radius + b2.radius;

          if (distSq < minDist * minDist && distSq > 0.0001) {
            const dist = Math.sqrt(distSq);
            const nx = dx / dist;
            const ny = dy / dist;

            // めり込み解消（位置補正）
            const overlap = minDist - dist;
            const separation = overlap * 0.5;
            b1.x -= nx * separation;
            b1.y -= ny * separation;
            b2.x += nx * separation;
            b2.y += ny * separation;

            // 法線方向の相対速度
            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const normalVel = nx * kx + ny * ky;

            // 衝突によって互いに接近している場合のみ反発インパルス適用
            if (normalVel > 0) {
              const m1 = b1.radius;
              const m2 = b2.radius;
              const impulse = ((1 + currentSettings.restitution) * normalVel) / (1 / m1 + 1 / m2);

              b1.vx -= (impulse / m1) * nx;
              b1.vy -= (impulse / m1) * ny;
              b2.vx += (impulse / m2) * nx;
              b2.vy += (impulse / m2) * ny;

              b1.bounceCount = (b1.bounceCount || 0) + 1;
              b2.bounceCount = (b2.bounceCount || 0) + 1;
            }
          }
        }
      }

      // 3. ボールの描画
      for (let i = 0; i < len; i++) {
        const b = balls[i];

        // ボール本体グラデーション
        const grad = ctx.createRadialGradient(
          b.x - b.radius * 0.3,
          b.y - b.radius * 0.3,
          b.radius * 0.1,
          b.x,
          b.y,
          b.radius
        );
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, b.color);
        grad.addColorStop(1, '#0f172a');

        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
        ctx.fillStyle = grad;
        ctx.fill();

        // 輪郭グロー
        ctx.strokeStyle = b.color;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }

      // 4. ドラッグ時のスリングショット引っ張り線および射出予測矢印の描画
      if (dragStartRef.current && currentDragRef.current) {
        const start = dragStartRef.current;
        const curr = currentDragRef.current;
        const pullDx = curr.x - start.x;
        const pullDy = curr.y - start.y;
        const pullDist = Math.hypot(pullDx, pullDy);

        // 手元の引っ張りゴムライン
        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(curr.x, curr.y);
        ctx.strokeStyle = 'rgba(148, 163, 184, 0.6)';
        ctx.lineWidth = 2;
        ctx.setLineDash([4, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        // 引っ張り起点のサークル
        ctx.beginPath();
        ctx.arc(start.x, start.y, 6, 0, Math.PI * 2);
        ctx.fillStyle = '#38bdf8';
        ctx.fill();

        // 手元側のサークル
        ctx.beginPath();
        ctx.arc(curr.x, curr.y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#94a3b8';
        ctx.fill();

        // スリングショット射出方向の予測矢印（引っ張りと逆方向）
        if (pullDist > 8) {
          const aimScale = 1.2;
          const aimX = start.x - pullDx * aimScale;
          const aimY = start.y - pullDy * aimScale;

          ctx.beginPath();
          ctx.moveTo(start.x, start.y);
          ctx.lineTo(aimX, aimY);
          ctx.strokeStyle = '#38bdf8';
          ctx.lineWidth = 2.5;
          ctx.stroke();

          // 矢印の鏃（あじろ）を描画
          const angle = Math.atan2(-pullDy, -pullDx);
          const headLength = 12;
          ctx.beginPath();
          ctx.moveTo(aimX, aimY);
          ctx.lineTo(
            aimX - headLength * Math.cos(angle - Math.PI / 6),
            aimY - headLength * Math.sin(angle - Math.PI / 6)
          );
          ctx.moveTo(aimX, aimY);
          ctx.lineTo(
            aimX - headLength * Math.cos(angle + Math.PI / 6),
            aimY - headLength * Math.sin(angle + Math.PI / 6)
          );
          ctx.strokeStyle = '#38bdf8';
          ctx.lineWidth = 2.5;
          ctx.stroke();
        }
      }

      animationFrameRef.current = requestAnimationFrame(loop);
    };

    animationFrameRef.current = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

  // ポインター操作（クリック/ドラッグして投げる）
  const getCanvasCoords = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
    };
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    const coords = getCanvasCoords(e);
    dragStartRef.current = coords;
    currentDragRef.current = coords;
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!dragStartRef.current) return;
    currentDragRef.current = getCanvasCoords(e);
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!dragStartRef.current) return;
    const start = dragStartRef.current;
    const end = getCanvasCoords(e);

    // ドラッグ移動量から投擲速度を計算
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const dist = Math.hypot(dx, dy);

    let vx = 0;
    let vy = 0;

    if (dist > 8) {
      // 引っ張った逆方向に飛ばす（スリングショット操作）
      vx = -dx * 0.12;
      vy = -dy * 0.12;
    } else {
      // 単純タップ時は少しランダムな初速
      vx = (Math.random() - 0.5) * 4;
      vy = (Math.random() - 0.8) * 3;
    }

    const newBall: Ball = {
      id: nextIdRef.current++,
      x: start.x,
      y: start.y,
      vx,
      vy,
      radius: 10 + Math.random() * 14,
      color: BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)],
      bounceCount: 0,
    };

    ballsRef.current.push(newBall);
    setBallCount(ballsRef.current.length);

    dragStartRef.current = null;
    currentDragRef.current = null;
  };

  // コントロールハンドラ
  const handleClear = () => {
    ballsRef.current = [];
    setBallCount(0);
  };

  const handleAddMultiple = (count: number) => {
    const canvas = canvasRef.current;
    const w = canvas ? canvas.width : 800;
    const h = canvas ? canvas.height : 450;
    const newBalls: Ball[] = [];

    for (let i = 0; i < count; i++) {
      newBalls.push({
        id: nextIdRef.current++,
        x: 40 + Math.random() * Math.max(w - 80, 100),
        y: 30 + Math.random() * Math.max(h * 0.4, 60),
        vx: (Math.random() - 0.5) * 8,
        vy: (Math.random() - 0.5) * 5,
        radius: 8 + Math.random() * 14,
        color: BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)],
        bounceCount: 0,
      });
    }

    ballsRef.current = [...ballsRef.current, ...newBalls];
    setBallCount(ballsRef.current.length);
  };

  const handleResetSettings = () => {
    setSettings(DEFAULT_SETTINGS);
  };

  return (
    <div className="sim-container">
      <header className="sim-header">
        <h1 className="sim-title">物理跳躍シミュレーション</h1>
        <p className="sim-subtitle">
          重力・反発係数・摩擦によるボールの跳ね返り挙動。タップで生成、ドラッグで狙って発射できます。
        </p>
      </header>

      <main className="canvas-wrapper">
        <div className="canvas-hint">
          クリック/タップ: 追加 | ドラッグ: 引っ張って逆方向に射出
        </div>
        <canvas
          ref={canvasRef}
          className="canvas-element"
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={() => {
            dragStartRef.current = null;
            currentDragRef.current = null;
          }}
        />
      </main>

      <Controls
        settings={settings}
        onSettingsChange={setSettings}
        ballCount={ballCount}
        onClear={handleClear}
        onAddMultiple={handleAddMultiple}
        onResetSettings={handleResetSettings}
      />
    </div>
  );
}
